{
  "sop_id": "SOP-021",
  "title": "Employee document verification",
  "steps": [
    {
      "step_id": "S1",
      "name": "Open ticket and take ownership",
      "role": "Executor",
      "type": "intake"
    },
    {
      "step_id": "S2",
      "name": "Verify checklist completeness and document readability",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S3",
      "name": "Verify identity and address proofs",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S4",
      "name": "Send education and employment confirmations to issuing institutions or background-verification agency",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "D1",
      "name": "Wait for confirmations from outside",
      "role": "System",
      "type": "rework"
    },
    {
      "step_id": "S5",
      "name": "Cross-check names, dates, grade, and salary with offer letter and HRMS",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S6",
      "name": "Record verification status",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S7",
      "name": "Submit ticket",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "A1",
      "name": "Incharge approval or rejection with reason",
      "role": "Incharge",
      "type": "approval"
    },
    {
      "step_id": "A2",
      "name": "Lead approval (if discrepancy found)",
      "role": "Lead",
      "type": "approval"
    },
    {
      "step_id": "R1",
      "name": "Correct and resubmit if rejected",
      "role": "Executor",
      "type": "rework"
    }
  ],
  "approvals": [
    {
      "stage": "Incharge",
      "condition": "always"
    },
    {
      "stage": "Lead",
      "condition": "if discrepancy found"
    }
  ],
  "dependencies": [
    {
      "dep_id": "D1",
      "provider": "Issuing institutions / Background-verification agency",
      "item": "Education and employment confirmations",
      "parallel_group": "P1"
    }
  ],
  "rework_reasons": [
    "Required document missing",
    "Incorrect category",
    "Amount mismatch",
    "Wrong quantity"
  ],
  "first_pass_yield_target": 0.9
}
